            var pigZombieInstance = instances().impl(spawnedIds.get(pigZombieId));
            var pigZombieControlInstance = instances().impl(spawnedIds.get(pigZombieControlId));
            var raiderInstance = instances().impl(spawnedIds.get(raiderId));
