    private void runImportedBeeStingerLossSelfTest(Location origin) {
        // Let the larger entity-options self-test finish its synchronous setup
        // before native Bee AI is asked to produce an attack event.
        getServer().getScheduler().runTaskLater(this,
                () -> runImportedBeeStingerLossSelfTest(origin, 0), 1L);
    }

    private void runImportedBeeStingerLossSelfTest(Location origin, int retryCount) {
        var selectedObserver = getServer().getPlayerExact("HelsteraTester");
        if (selectedObserver == null || !selectedObserver.isValid() || selectedObserver.isDead()
                || !selectedObserver.getWorld().equals(origin.getWorld())) {
            selectedObserver = getServer().getOnlinePlayers().stream()
                    .filter(player -> player.isValid() && !player.isDead()
                            && player.getWorld().equals(origin.getWorld()))
                    .min(java.util.Comparator.comparingDouble(player ->
                            player.getLocation().distanceSquared(origin)))
                    .orElse(null);
        }
        final var observer = selectedObserver;
        if (observer == null) {
            if (retryCount >= 180) {
                getLogger().info("[自检] bee-stinger-loss-imported result=false imported=false"
                        + " reason=no-active-player-observer retries=" + retryCount);
                return;
            }
            getServer().getScheduler().runTaskLater(this,
                    () -> runImportedBeeStingerLossSelfTest(origin, retryCount + 1), 20L);
            return;
        }

        Path sourceRoot = null;
        Path outputDirectory = getDataFolder().toPath().resolve("mobs").normalize();
        boolean outputDirectoryExisted = Files.isDirectory(outputDirectory);
        var mobFiles = new java.util.ArrayList<Path>();
        var instanceIds = new java.util.ArrayList<Integer>();
        org.bukkit.entity.Zombie[] probeTarget = {null};
        int[] probeTicks = {0};
        org.bukkit.event.Listener attackListener = null;
        boolean[] cleanupDeferred = {false};
        try {
            String suffix = java.util.UUID.randomUUID().toString().replace("-", "").substring(0, 8);
            sourceRoot = Files.createTempDirectory("helstera-bee-stinger-import-");
            Path sourceDirectory = Files.createDirectories(sourceRoot.resolve("Mobs"));
            Path source = sourceDirectory.resolve("bee-stinger-loss.yml");
            String protectedMobId = "ImportedBeeStingerProtected_" + suffix;
            String controlMobId = "ImportedBeeStingerControl_" + suffix;
            Files.writeString(source, """
                    mobs:
                      %1$s:
                        Type: BEE
                        Options:
                          HasStung: false
                          PreventStingerLoss: true
                      %2$s:
                        Type: BEE
                        Options:
                          HasStung: false
                          PreventStingerLoss: false
                    """.formatted(protectedMobId, controlMobId));

            var converted = new MythicMobsImporter().convert(source, sourceRoot);
            var targetIds = new java.util.LinkedHashMap<String, String>();
            for (var entry : converted) {
                if (!(entry.get("target-file") instanceof String targetFile)
                        || !targetFile.startsWith("mobs/") || !targetFile.endsWith(".yml")
                        || !"mapped".equals(entry.get("status"))) continue;
                Path destination = getDataFolder().toPath().resolve(targetFile).normalize();
                if (!destination.startsWith(outputDirectory)) {
                    throw new IOException("Importer returned an unsafe Bee stinger path: " + targetFile);
                }
                Files.createDirectories(destination.getParent());
                if (Files.exists(destination)) {
                    throw new IOException("Refusing to overwrite existing Bee stinger config: " + destination);
                }
                mobFiles.add(destination);
                Files.writeString(destination, String.valueOf(entry.get("content")));
                targetIds.put(String.valueOf(entry.get("source-mob-id")),
                        String.valueOf(entry.get("target-mob-id")));
            }

            String protectedTargetId = targetIds.get(protectedMobId);
            String controlTargetId = targetIds.get(controlMobId);
            if (protectedTargetId == null || controlTargetId == null) {
                throw new IllegalStateException("Mythic Bee stinger options were not imported for both probe mobs");
            }
            // Paper's native entity activation requires a nearby player. The
            // integration server connects its observer after plugin startup,
            // so wait above and keep the native AI probe in that player's area.
            Location probeOrigin = observer.getLocation().clone();
            probeOrigin.getChunk().load();
            MobSpawn protectedSpawn = spawnMobCore(protectedTargetId, "example/emberling", probeOrigin,
                    false, null);
            MobSpawn controlSpawn = spawnMobCore(controlTargetId, "example/emberling",
                    probeOrigin.clone().add(3, 0, 0), false, null);
            if (protectedSpawn != null && protectedSpawn.instanceId() > 0) {
                instanceIds.add(protectedSpawn.instanceId());
            }
            if (controlSpawn != null && controlSpawn.instanceId() > 0) {
                instanceIds.add(controlSpawn.instanceId());
            }
            var protectedInstance = protectedSpawn == null || protectedSpawn.instanceId() <= 0
                    ? null : instances().impl(protectedSpawn.instanceId());
            var controlInstance = controlSpawn == null || controlSpawn.instanceId() <= 0
                    ? null : instances().impl(controlSpawn.instanceId());
            var protectedBee = protectedInstance == null ? null
                    : protectedInstance.baseEntity().filter(org.bukkit.entity.Bee.class::isInstance)
                    .map(org.bukkit.entity.Bee.class::cast).orElse(null);
            var controlBee = controlInstance == null ? null
                    : controlInstance.baseEntity().filter(org.bukkit.entity.Bee.class::isInstance)
                    .map(org.bukkit.entity.Bee.class::cast).orElse(null);
            var protectedConfig = mobConfig(protectedTargetId);
            var controlConfig = mobConfig(controlTargetId);
            boolean imported = protectedBee != null && controlBee != null
                    && protectedInstance.options().preventStingerLoss()
                    && !controlInstance.options().preventStingerLoss()
                    && protectedConfig.getBoolean("mob.prevent-stinger-loss")
                    && !controlConfig.getBoolean("mob.prevent-stinger-loss", true)
                    && !protectedBee.hasStung() && !controlBee.hasStung();
            if (!imported) {
                getLogger().info("[自检] bee-stinger-loss-imported result=false imported=false"
                        + " protected-option=" + (protectedInstance != null
                            && protectedInstance.options().preventStingerLoss())
                        + " control-option=" + (controlInstance != null
                            && controlInstance.options().preventStingerLoss()));
                return;
            }

            var target = origin.getWorld().spawn(probeOrigin.clone().add(4, 0, 0),
                    org.bukkit.entity.Zombie.class);
            probeTarget[0] = target;
            target.setPersistent(true);
            target.setAI(false);
            target.setGravity(false);
            target.setSilent(true);
            target.setMaxHealth(40.0);
            target.setHealth(target.getMaxHealth());
            target.setInvulnerable(false);
            target.getEquipment().setHelmet(new org.bukkit.inventory.ItemStack(
                    org.bukkit.Material.CARVED_PUMPKIN));
            target.getEquipment().setHelmetDropChance(0.0f);
            target.addPotionEffect(new org.bukkit.potion.PotionEffect(
                    org.bukkit.potion.PotionEffectType.RESISTANCE, 600, 3, false, false, false));
            protectedBee.teleport(target.getLocation().clone().add(-2, 1, 0));
            controlBee.teleport(target.getLocation().clone().add(2, 1, 0));

            var protectedAttacks = new java.util.concurrent.atomic.AtomicInteger();
            var controlAttacks = new java.util.concurrent.atomic.AtomicInteger();
            var protectedEvents = new java.util.concurrent.atomic.AtomicInteger();
            var controlEvents = new java.util.concurrent.atomic.AtomicInteger();
            var protectedCancelled = new java.util.concurrent.atomic.AtomicInteger();
            var controlCancelled = new java.util.concurrent.atomic.AtomicInteger();
            var registeredAttackListener = new org.bukkit.event.Listener() {
                @org.bukkit.event.EventHandler(priority = org.bukkit.event.EventPriority.MONITOR)
                public void onBeeAttack(org.bukkit.event.entity.EntityDamageByEntityEvent event) {
                    if (event.getDamager() == protectedBee && event.getEntity() == target) {
                        protectedEvents.incrementAndGet();
                        if (event.isCancelled()) protectedCancelled.incrementAndGet();
                        else protectedAttacks.incrementAndGet();
                    }
                    if (event.getDamager() == controlBee && event.getEntity() == target) {
                        controlEvents.incrementAndGet();
                        if (event.isCancelled()) controlCancelled.incrementAndGet();
                        else controlAttacks.incrementAndGet();
                    }
                }
            };
            attackListener = registeredAttackListener;
            getServer().getPluginManager().registerEvents(registeredAttackListener, this);
            protectedBee.setAI(true);
            protectedBee.setHasStung(false);
            protectedBee.setAware(true);
            protectedBee.setAnger(1200);
            protectedBee.setTarget(target);
            controlBee.setAI(false);
            controlBee.setHasStung(false);
            final boolean[] controlStarted = {false};
            final boolean[] protectedRestoredObserved = {false};
            final boolean[] controlRetainedObserved = {false};
            final org.bukkit.scheduler.BukkitTask[] attackTask = {null};

            Path cleanupSourceRoot = sourceRoot;
            java.util.List<Path> cleanupMobFiles = java.util.List.copyOf(mobFiles);
            java.util.List<Integer> cleanupInstanceIds = java.util.List.copyOf(instanceIds);
            boolean cleanupOutputDirectoryExisted = outputDirectoryExisted;
            attackTask[0] = getServer().getScheduler().runTaskTimer(this, () -> {
                probeTicks[0]++;
                boolean terminal = false;
                try {
                    if (observer.isValid() && !observer.isDead()
                            && observer.getWorld().equals(target.getWorld())
                            && observer.getLocation().distanceSquared(target.getLocation()) > 64.0) {
                        Location activeOrigin = observer.getLocation().clone().add(4, 0, 0);
                        target.teleport(activeOrigin);
                        protectedBee.teleport(activeOrigin.clone().add(-2, 1, 0));
                        controlBee.teleport(activeOrigin.clone().add(2, 1, 0));
                        protectedBee.setTarget(target);
                        controlBee.setTarget(target);
                    }
                    if (target.isValid() && !target.isDead()) {
                        target.setInvulnerable(false);
                        target.setGravity(false);
                        target.setFireTicks(0);
                        if (target.getHealth() < target.getMaxHealth()) {
                            target.setHealth(target.getMaxHealth());
                        }
                        if (target.getNoDamageTicks() > 0) target.setNoDamageTicks(0);
                        var activeResistance = target.getPotionEffect(
                                org.bukkit.potion.PotionEffectType.RESISTANCE);
                        if (activeResistance == null || activeResistance.getAmplifier() != 3) {
                            target.removePotionEffect(org.bukkit.potion.PotionEffectType.RESISTANCE);
                            target.addPotionEffect(new org.bukkit.potion.PotionEffect(
                                    org.bukkit.potion.PotionEffectType.RESISTANCE,
                                    600, 3, false, false, false));
                        }
                        if (protectedAttacks.get() == 0) {
                            maintainBeeProbeTarget(protectedBee, target, -2.0);
                        }
                    }
                    if (protectedAttacks.get() > 0 && protectedBee.hasAI()) protectedBee.setAI(false);
                    if (!controlStarted[0] && probeTicks[0] >= 30) {
                        controlStarted[0] = true;
                        controlBee.setAI(true);
                        controlBee.setAware(true);
                        controlBee.setAnger(1200);
                        controlBee.teleport(target.getLocation().clone().add(1.25, 1, 0));
                        controlBee.setTarget(target);
                    }
                    if (controlStarted[0] && controlAttacks.get() == 0
                            && target.isValid() && !target.isDead()) {
                        maintainBeeProbeTarget(controlBee, target, 1.25);
                    }
                    if (controlAttacks.get() > 0 && controlBee.hasAI()) controlBee.setAI(false);
                    boolean protectedAttacked = protectedAttacks.get() > 0;
                    boolean controlAttacked = controlAttacks.get() > 0;
                    if (protectedAttacked && !protectedBee.hasStung()) protectedRestoredObserved[0] = true;
                    if (controlAttacked && controlBee.hasStung()) controlRetainedObserved[0] = true;
                    boolean protectedRestored = protectedRestoredObserved[0];
                    boolean controlRetained = controlRetainedObserved[0];
                    var targetResistance = target.getPotionEffect(
                            org.bukkit.potion.PotionEffectType.RESISTANCE);
                    int targetResistanceAmplifier = targetResistance == null
                            ? -1 : targetResistance.getAmplifier();
                    boolean targetReady = target.isValid()
                            && !target.isDead()
                            && !target.isInvulnerable()
                            && targetResistanceAmplifier == 3;
                    boolean passed = imported && protectedAttacked && controlAttacked
                            && protectedRestored && controlRetained && targetReady
                            && protectedCancelled.get() == 0 && controlCancelled.get() == 0;
                    if (!(passed || probeTicks[0] >= 240)) return;
                    terminal = true;
                    if (attackTask[0] != null) attackTask[0].cancel();
                    if (!passed) {
                        getLogger().info("[自检] bee-stinger-loss-diagnostic"
                                + " observer=" + observer.getName()
                                + " observer-distance=" + observer.getLocation().distance(target.getLocation())
                                + " protected-ai=" + protectedBee.hasAI()
                                + " control-ai=" + controlBee.hasAI()
                                + " protected-aware=" + protectedBee.isAware()
                                + " control-aware=" + controlBee.isAware()
                                + " protected-anger=" + protectedBee.getAnger()
                                + " control-anger=" + controlBee.getAnger()
                                + " protected-target=" + (protectedBee.getTarget() == target)
                                + " control-target=" + (controlBee.getTarget() == target)
                                + " target-chunk-loaded=" + target.getChunk().isLoaded());
                    }
                    getLogger().info("[自检] bee-stinger-loss-imported result=" + passed
                            + " imported=" + imported
                            + " target-entity=ZOMBIE"
                            + " target-ai=" + target.hasAI()
                            + " target-invulnerable=" + target.isInvulnerable()
                            + " target-resistance-amplifier=" + targetResistanceAmplifier
                            + " protected-option=true control-option=false"
                            + " protected-attacks=" + protectedAttacks.get()
                            + " control-attacks=" + controlAttacks.get()
                            + " protected-events=" + protectedEvents.get()
                            + " control-events=" + controlEvents.get()
                            + " protected-cancelled=" + protectedCancelled.get()
                            + " control-cancelled=" + controlCancelled.get()
                            + " protected-restored=" + protectedRestored
                            + " control-retained=" + controlRetained
                            + " protected-near=" + beeProbeNear(protectedBee, target)
                            + " control-near=" + beeProbeNear(controlBee, target)
                            + " trigger=entity-target-api"
                            + " event=native-ai");
                } catch (Throwable failure) {
                    terminal = true;
                    getLogger().warning("[自检] bee-stinger-loss-imported result=false error=" + failure);
                } finally {
                    if (terminal) {
                        if (attackTask[0] != null) attackTask[0].cancel();
                        try {
                            org.bukkit.event.HandlerList.unregisterAll(registeredAttackListener);
                        } finally {
                            try {
                                if (target.isValid()) target.remove();
                            } finally {
                                cleanupImportedMobProbe(cleanupSourceRoot, outputDirectory,
                                        cleanupOutputDirectoryExisted, cleanupMobFiles, cleanupInstanceIds);
                            }
                        }
                    }
                }
            }, 1L, 1L);
            cleanupDeferred[0] = true;
        } catch (Throwable failure) {
            getLogger().warning("[自检] bee-stinger-loss-imported result=false error=" + failure);
        } finally {
            if (!cleanupDeferred[0]) {
                try {
                    if (attackListener != null) org.bukkit.event.HandlerList.unregisterAll(attackListener);
                    if (probeTarget[0] != null && probeTarget[0].isValid()) probeTarget[0].remove();
                } finally {
                    cleanupImportedMobProbe(sourceRoot, outputDirectory,
                            outputDirectoryExisted, mobFiles, instanceIds);
                }
            }
        }
    }

    private boolean runImportedItemSimilarityProbe(SkillService skills,
            BehaviorRegistry behaviors,
            dev.helstera.api.behavior.BehaviorContext triggerItemContext,
            dev.helstera.api.behavior.BehaviorContext inventoryContext,
            Player player) {
        var entityPrimary = dev.helstera.migration.importer.MmConditions.translate(
                "?entityItemIsSimilar{i=STONE}");
        var entityAlias = dev.helstera.migration.importer.MmConditions.translate(
                "?entityItemIsSimilar{m=STONE}");
        var entityNegative = dev.helstera.migration.importer.MmConditions.translate(
                "?entityItemIsSimilar{item=DIAMOND}");
        var entityInvalid = dev.helstera.migration.importer.MmConditions.translate(
                "?entityItemIsSimilar{unknown=STONE}");
        boolean entityPrimaryMapped = entityPrimary.translated()
                && "entity-item-is-similar STONE".equals(entityPrimary.condition());
        boolean entityAliasMapped = entityAlias.translated()
                && "entity-item-is-similar STONE".equals(entityAlias.condition());
        boolean entityNegativeMapped = entityNegative.translated()
                && "entity-item-is-similar DIAMOND".equals(entityNegative.condition());
        String entityPrimaryKey = entityPrimaryMapped ? skills.bindCondition(entityPrimary.condition()) : null;
        String entityAliasKey = entityAliasMapped ? skills.bindCondition(entityAlias.condition()) : null;
        String entityNegativeKey = entityNegativeMapped ? skills.bindCondition(entityNegative.condition()) : null;
        boolean entityPositive = entityPrimaryKey != null
                && behaviors.testCondition(entityPrimaryKey, triggerItemContext);
        boolean entityAliasPositive = entityAliasKey != null
                && behaviors.testCondition(entityAliasKey, triggerItemContext);
        boolean entityNegativeResult = entityNegativeKey != null
                && !behaviors.testCondition(entityNegativeKey, triggerItemContext);
        boolean entityInvalidPreserved = !entityInvalid.translated()
                && "?entityItemIsSimilar{unknown=STONE}".equals(entityInvalid.condition());

        var inventoryPrimary = dev.helstera.migration.importer.MmConditions.translate(
                "?itemIsSimilar{i=SHIELD;slot=HAND}");
        var inventoryAlias = dev.helstera.migration.importer.MmConditions.translate(
                "?similarTo{item=SHIELD;s=HAND}");
        var inventoryNegative = dev.helstera.migration.importer.MmConditions.translate(
                "?itemIsSimilar{i=SHIELD;slot=OFF_HAND}");
        var inventoryInvalid = dev.helstera.migration.importer.MmConditions.translate(
                "?itemIsSimilar{i=SHIELD;unknown=true}");
        boolean inventoryPrimaryMapped = inventoryPrimary.translated()
                && "item-is-similar SHIELD HAND".equals(inventoryPrimary.condition());
        boolean inventoryAliasMapped = inventoryAlias.translated()
                && "item-is-similar SHIELD HAND".equals(inventoryAlias.condition());
        boolean inventoryNegativeMapped = inventoryNegative.translated()
                && "item-is-similar SHIELD OFF_HAND".equals(inventoryNegative.condition());
        String inventoryPrimaryKey = inventoryPrimaryMapped ? skills.bindCondition(inventoryPrimary.condition()) : null;
        String inventoryAliasKey = inventoryAliasMapped ? skills.bindCondition(inventoryAlias.condition()) : null;
        String inventoryNegativeKey = inventoryNegativeMapped ? skills.bindCondition(inventoryNegative.condition()) : null;
        boolean inventoryPositive;
        boolean inventoryAliasPositive;
        boolean inventoryNegativeResult;
        org.bukkit.inventory.ItemStack previousOffHand = player.getInventory().getItemInOffHand();
        if (previousOffHand != null) previousOffHand = previousOffHand.clone();
        try {
            player.getInventory().setItemInOffHand(new org.bukkit.inventory.ItemStack(org.bukkit.Material.AIR));
            inventoryPositive = inventoryPrimaryKey != null
                    && behaviors.testCondition(inventoryPrimaryKey, inventoryContext);
            inventoryAliasPositive = inventoryAliasKey != null
                    && behaviors.testCondition(inventoryAliasKey, inventoryContext);
            inventoryNegativeResult = inventoryNegativeKey != null
                    && !behaviors.testCondition(inventoryNegativeKey, inventoryContext);
        } finally {
            player.getInventory().setItemInOffHand(previousOffHand);
        }
        boolean inventoryInvalidPreserved = !inventoryInvalid.translated()
                && "?itemIsSimilar{i=SHIELD;unknown=true}".equals(inventoryInvalid.condition());
        boolean result = entityPrimaryMapped && entityAliasMapped && entityNegativeMapped
                && entityPositive && entityAliasPositive && entityNegativeResult && entityInvalidPreserved
                && inventoryPrimaryMapped && inventoryAliasMapped && inventoryNegativeMapped
                && inventoryPositive && inventoryAliasPositive && inventoryNegativeResult
                && inventoryInvalidPreserved;
        getLogger().info("[自检] imported-item-similarity-conditions entity-primary-mapped="
                + entityPrimaryMapped + " entity-alias-mapped=" + entityAliasMapped
                + " entity-positive=" + entityPositive + " entity-alias-positive=" + entityAliasPositive
                + " entity-negative=" + entityNegativeResult + " entity-invalid-preserved="
                + entityInvalidPreserved + " inventory-primary-mapped=" + inventoryPrimaryMapped
                + " inventory-alias-mapped=" + inventoryAliasMapped + " inventory-positive="
                + inventoryPositive + " inventory-alias-positive=" + inventoryAliasPositive
                + " inventory-negative=" + inventoryNegativeResult + " inventory-invalid-preserved="
                + inventoryInvalidPreserved + " result=" + result);
        return result;
    }

    private void maintainBeeProbeTarget(org.bukkit.entity.Bee bee,
            org.bukkit.entity.LivingEntity target, double horizontalOffset) {
        var targetLocation = target.getLocation();
        if (!bee.getWorld().equals(target.getWorld())
                || bee.getLocation().distanceSquared(targetLocation) > 25.0) {
            bee.teleport(targetLocation.clone().add(horizontalOffset, 1, 0));
        }
        bee.setAware(true);
        bee.setAnger(1200);
        if (bee.getTarget() != target) bee.setTarget(target);
    }

    private boolean beeProbeNear(org.bukkit.entity.Bee bee, org.bukkit.entity.LivingEntity target) {
        return bee.getWorld().equals(target.getWorld())
                && bee.getLocation().distanceSquared(target.getLocation()) <= 64.0;
    }

    private void cleanupImportedMobProbe(Path sourceRoot, Path outputDirectory,
            boolean outputDirectoryExisted, java.util.List<Path> mobFiles, java.util.List<Integer> instanceIds) {
        for (int instanceId : instanceIds) {
            try {
                if (instances() != null) instances().despawn(instanceId);
            } catch (RuntimeException ignored) { }
        }
        if (sourceRoot != null) {
            try (var paths = Files.walk(sourceRoot)) {
                for (Path path : paths.sorted(java.util.Comparator.reverseOrder()).toList()) {
                    Files.deleteIfExists(path);
                }
            } catch (IOException cleanupFailure) {
                getLogger().warning("imported mob probe source cleanup failed=" + cleanupFailure);
            }
        }
        for (Path mobFile : mobFiles) {
            try { Files.deleteIfExists(mobFile); }
            catch (IOException cleanupFailure) {
                getLogger().warning("imported mob probe target cleanup failed=" + cleanupFailure);
            }
        }
        if (!outputDirectoryExisted) {
            try { Files.deleteIfExists(outputDirectory); }
            catch (IOException ignored) { }
        }
    }

    private void runImportedTemplateTypeSelfTest() {
        getServer().getScheduler().runTaskLater(this, () -> {
            Path sourceRoot = null;
            Path outputDirectory = getDataFolder().toPath().resolve("mobs").normalize();
            boolean outputDirectoryExisted = Files.isDirectory(outputDirectory);
            var mobFiles = new java.util.ArrayList<Path>();
            var instanceIds = new java.util.ArrayList<Integer>();
            org.bukkit.entity.Entity missingConfigProbe = null;
            org.bukkit.entity.Entity unmanagedProbe = null;
            try {
                if (!(skillService instanceof SkillService skills)
                        || !(behaviorRegistry instanceof dev.helstera.ai.BehaviorRegistryImpl behavior)) {
                    throw new IllegalStateException("skill runtime is unavailable");
                }
                org.bukkit.World world = getServer().getWorlds().isEmpty()
                        ? null : getServer().getWorlds().get(0);
                if (world == null || mobTemplateIndex == null) {
                    throw new IllegalStateException("world or mob-template index is unavailable");
                }
                String suffix = java.util.UUID.randomUUID().toString().replace("-", "").substring(0, 8);
                String ancestorSourceId = "TemplateTypeAncestor_" + suffix;
                String parentSourceId = "TemplateTypeParent_" + suffix;
                String childSourceId = "TemplateTypeChild_" + suffix;
                String controlSourceId = "TemplateTypeControl_" + suffix;
                String excludeSourceId = "TemplateTypeExclude_" + suffix;
                sourceRoot = Files.createTempDirectory("helstera-template-type-import-");
                Path source = Files.createDirectories(sourceRoot.resolve("Mobs"))
                        .resolve("template-type.yml");
                Files.writeString(source, """
                        mobs:
                          %1$s:
                            Type: ZOMBIE
                            Health: 31
                            Options:
                              NoAI: true
                              PreventSunburn: true
                          %2$s:
                            Type: ZOMBIE
                            Template: %1$s
                            Health: 37
                          %3$s:
                            Type: ZOMBIE
                            Template: %2$s
                          %4$s:
                            Type: ZOMBIE
                          %5$s:
                            Type: ZOMBIE
                            Template: %2$s
                            Exclude: [Health, Options]
                            Health: 42
                            Options:
                              NoAI: false
                        """.formatted(ancestorSourceId, parentSourceId, childSourceId, controlSourceId,
                        excludeSourceId));

                Map<String, String> targetIds = new LinkedHashMap<>();
                for (Map<String, Object> entry : new MythicMobsImporter().convert(source, sourceRoot)) {
                    if (!(entry.get("target-file") instanceof String targetFile)
                            || !targetFile.startsWith("mobs/") || !targetFile.endsWith(".yml")
                            || !"mapped".equals(entry.get("status"))) continue;
                    Path destination = getDataFolder().toPath().resolve(targetFile).normalize();
                    if (!destination.startsWith(outputDirectory)) {
                        throw new IOException("unsafe imported template-type mob path: " + targetFile);
                    }
                    Files.createDirectories(destination.getParent());
                    if (Files.exists(destination)) {
                        throw new IOException("refusing to overwrite template-type probe config: " + destination);
                    }
                    mobFiles.add(destination);
                    YamlConfiguration imported = YamlConfiguration.loadConfiguration(
                            new java.io.StringReader(String.valueOf(entry.get("content"))));
                    imported.set("model", "example/emberling");
                    imported.set("entity.silent", true);
                    Files.writeString(destination, imported.saveToString());
                    targetIds.put(String.valueOf(entry.get("source-mob-id")),
                            String.valueOf(entry.get("target-mob-id")));
                }

                String childId = targetIds.get(childSourceId);
                String controlId = targetIds.get(controlSourceId);
                String parentId = targetIds.get(parentSourceId);
                String ancestorId = targetIds.get(ancestorSourceId);
                String excludeId = targetIds.get(excludeSourceId);
                if (childId == null || controlId == null || parentId == null || ancestorId == null
                        || excludeId == null) {
                    throw new IllegalStateException("one or more imported template-type mobs are missing");
                }
                mobTemplateIndex.invalidate();
                Location origin = world.getSpawnLocation().clone().add(0, 2, 0);
                int childInstanceId = spawnMobAt(childId, origin, null);
                int controlInstanceId = spawnMobAt(controlId, origin.clone().add(3, 0, 0), null);
                int excludeInstanceId = spawnMobAt(excludeId, origin.clone().add(6, 0, 0), null);
                if (childInstanceId > 0) instanceIds.add(childInstanceId);
                if (controlInstanceId > 0) instanceIds.add(controlInstanceId);
                if (excludeInstanceId > 0) instanceIds.add(excludeInstanceId);
                var childInstance = childInstanceId > 0 ? instances().impl(childInstanceId) : null;
                var controlInstance = controlInstanceId > 0 ? instances().impl(controlInstanceId) : null;
                var excludeInstance = excludeInstanceId > 0 ? instances().impl(excludeInstanceId) : null;
                org.bukkit.entity.LivingEntity child = childInstance == null ? null
                        : childInstance.baseEntity().filter(org.bukkit.entity.LivingEntity.class::isInstance)
                                .map(org.bukkit.entity.LivingEntity.class::cast).orElse(null);
                org.bukkit.entity.LivingEntity control = controlInstance == null ? null
                        : controlInstance.baseEntity().filter(org.bukkit.entity.LivingEntity.class::isInstance)
                                .map(org.bukkit.entity.LivingEntity.class::cast).orElse(null);
                org.bukkit.entity.LivingEntity excluded = excludeInstance == null ? null
                        : excludeInstance.baseEntity().filter(org.bukkit.entity.LivingEntity.class::isInstance)
                                .map(org.bukkit.entity.LivingEntity.class::cast).orElse(null);
                if (child == null || control == null || excluded == null) {
                    throw new IllegalStateException("managed child, control, or Exclude entity did not spawn");
                }

                var primary = dev.helstera.migration.importer.MmConditions.translate(
                        "?TemplateType{t=" + parentSourceId + "}");
                var alias = dev.helstera.migration.importer.MmConditions.translate(
                        "?InstanceOf{template=" + ancestorSourceId + "}");
                var negative = dev.helstera.migration.importer.MmConditions.translate(
                        "?Template{template=unrelated}");
                var invalid = dev.helstera.migration.importer.MmConditions.translate(
                        "?TemplateType{unknown=" + parentSourceId + "}");
                String primaryKey = primary.translated() ? skills.bindCondition(primary.condition()) : null;
                String aliasKey = alias.translated() ? skills.bindCondition(alias.condition()) : null;
                String negativeKey = negative.translated() ? skills.bindCondition(negative.condition()) : null;
                var childContext = dev.helstera.api.behavior.BehaviorContext.of(
                        null, child, 1.0, -1, 0, "IDLE");
                var controlContext = dev.helstera.api.behavior.BehaviorContext.of(
                        null, control, 1.0, -1, 0, "IDLE");
                boolean imported = mobConfig(childId).getStringList("mob.templates").contains(parentId)
                        && mobConfig(parentId).getStringList("mob.templates").contains(ancestorId);
                boolean primaryMapped = primary.translated() && primary.condition().startsWith("template-type ");
                boolean aliasMapped = alias.translated() && alias.condition().startsWith("template-type ");
                boolean directPositive = primaryKey != null && behavior.testCondition(primaryKey, childContext);
                boolean transitivePositive = aliasKey != null && behavior.testCondition(aliasKey, childContext);
                boolean unrelatedRejected = negativeKey != null
                        && !behavior.testCondition(negativeKey, childContext);
                boolean controlRejected = primaryKey != null
                        && !behavior.testCondition(primaryKey, controlContext);
                var inheritedHealthAttribute = child.getAttribute(org.bukkit.attribute.Attribute.GENERIC_MAX_HEALTH);
                var excludedHealthAttribute = excluded.getAttribute(org.bukkit.attribute.Attribute.GENERIC_MAX_HEALTH);
                boolean fieldInheritance = mobConfig(childId).getDouble("mob.health", -1) == 37.0
                        && inheritedHealthAttribute != null
                        && inheritedHealthAttribute.getBaseValue() == 37.0 && !child.hasAI()
                        && mobConfig(childId).getBoolean("entity.no-ai", false);
                boolean excludeInheritedRemoved = !mobConfig(excludeId).contains("entity.prevent-sunburn");
                boolean excludeOwnValues = mobConfig(excludeId).getDouble("mob.health", -1) == 42.0
                        && !mobConfig(excludeId).getBoolean("entity.no-ai", true)
                        && excludedHealthAttribute != null && excludedHealthAttribute.getBaseValue() == 42.0
                        && excluded.hasAI();
                missingConfigProbe = world.spawnEntity(origin.clone().add(6, 0, 0),
                        org.bukkit.entity.EntityType.ZOMBIE);
                dev.helstera.api.behavior.ManagedMobIdentity.mark(missingConfigProbe, "mythic_missing_template_probe");
                boolean missingConfigRejected = primaryKey != null && !behavior.testCondition(primaryKey,
                        dev.helstera.api.behavior.BehaviorContext.of(null,
                                (org.bukkit.entity.LivingEntity) missingConfigProbe, 1.0, -1, 0, "IDLE"));
                unmanagedProbe = world.spawnEntity(origin.clone().add(9, 0, 0),
                        org.bukkit.entity.EntityType.ZOMBIE);
                boolean unmanagedRejected = primaryKey != null && !behavior.testCondition(primaryKey,
                        dev.helstera.api.behavior.BehaviorContext.of(null,
                                (org.bukkit.entity.LivingEntity) unmanagedProbe, 1.0, -1, 0, "IDLE"));
                boolean invalidPreserved = !invalid.translated()
                        && invalid.condition().contains("unknown=" + parentSourceId);
                boolean passed = imported && primaryMapped && aliasMapped && directPositive
                        && transitivePositive && unrelatedRejected && controlRejected
                        && fieldInheritance && excludeInheritedRemoved && excludeOwnValues
                        && missingConfigRejected && unmanagedRejected && invalidPreserved;
                getLogger().info("[自检] template-type-imported result=" + passed
                        + " imported=" + imported + " primary-mapped=" + primaryMapped
                        + " alias-mapped=" + aliasMapped + " direct-positive=" + directPositive
                        + " transitive-positive=" + transitivePositive
                        + " unrelated-rejected=" + unrelatedRejected + " control-rejected=" + controlRejected
                        + " field-inheritance=" + fieldInheritance
                        + " exclude-inherited-removed=" + excludeInheritedRemoved
                        + " exclude-own-values=" + excludeOwnValues
                        + " missing-config-rejected=" + missingConfigRejected
                        + " unmanaged-rejected=" + unmanagedRejected
                        + " invalid-preserved=" + invalidPreserved + " passed=" + passed);
            } catch (Throwable failure) {
                getLogger().warning("[自检] template-type-imported result=false error=" + failure);
            } finally {
                if (missingConfigProbe != null && missingConfigProbe.isValid()) missingConfigProbe.remove();
                if (unmanagedProbe != null && unmanagedProbe.isValid()) unmanagedProbe.remove();
                cleanupImportedMobProbe(sourceRoot, outputDirectory,
                        outputDirectoryExisted, mobFiles, instanceIds);
                if (mobTemplateIndex != null) mobTemplateIndex.invalidate();
            }
        }, 80L);
    }

    private void runImportedCatOptionsSelfTest(org.bukkit.World world, Location origin) {
        Path sourceRoot = null;
        Path outputDirectory = getDataFolder().toPath().resolve("mobs").normalize();
        boolean outputDirectoryExisted = Files.isDirectory(outputDirectory);
        var mobFiles = new java.util.ArrayList<Path>();
        var instanceIds = new java.util.ArrayList<Integer>();
        try {
            String suffix = java.util.UUID.randomUUID().toString().replace("-", "").substring(0, 8);
            sourceRoot = Files.createTempDirectory("helstera-cat-options-import-");
            Path sourceDirectory = Files.createDirectories(sourceRoot.resolve("Mobs"));
            Path source = sourceDirectory.resolve("cat-options.yml");
            String configuredMobId = "ImportedCatConfigured_" + suffix;
            String controlMobId = "ImportedCatControl_" + suffix;
            Files.writeString(source, """
                    mobs:
                      %1$s:
                        Type: CAT
                        Options:
                          CatType: SIAMESE
                          Sitting: true
                          CollarColor: BLUE
                      %2$s:
                        Type: CAT
                        Options:
                          CatType: TABBY
                          Sitting: false
                          CollarColor: RED
                    """.formatted(configuredMobId, controlMobId));

            var converted = new MythicMobsImporter().convert(source, sourceRoot);
            var targetIds = new java.util.LinkedHashMap<String, String>();
            for (var entry : converted) {
                if (!(entry.get("target-file") instanceof String targetFile)
                        || !targetFile.startsWith("mobs/") || !targetFile.endsWith(".yml")
                        || !"mapped".equals(entry.get("status"))) continue;
                Path destination = getDataFolder().toPath().resolve(targetFile).normalize();
                if (!destination.startsWith(outputDirectory)) {
                    throw new IOException("Importer returned an unsafe Cat mob path: " + targetFile);
                }
                Files.createDirectories(destination.getParent());
                if (Files.exists(destination)) {
                    throw new IOException("Refusing to overwrite existing Cat mob config: " + destination);
                }
                mobFiles.add(destination);
                Files.writeString(destination, String.valueOf(entry.get("content")));
                targetIds.put(String.valueOf(entry.get("source-mob-id")),
                        String.valueOf(entry.get("target-mob-id")));
            }

            String configuredTargetId = targetIds.get(configuredMobId);
            String controlTargetId = targetIds.get(controlMobId);
            if (configuredTargetId == null || controlTargetId == null) {
                throw new IllegalStateException("Mythic Cat options were not imported for both probe mobs");
            }
            MobSpawn configuredSpawn = spawnMobCore(configuredTargetId, "example/emberling", origin,
                    false, null);
            MobSpawn controlSpawn = spawnMobCore(controlTargetId, "example/emberling",
                    origin.clone().add(3, 0, 0), false, null);
            if (configuredSpawn != null && configuredSpawn.instanceId() > 0) {
                instanceIds.add(configuredSpawn.instanceId());
            }
            if (controlSpawn != null && controlSpawn.instanceId() > 0) {
                instanceIds.add(controlSpawn.instanceId());
            }
            var configuredInstance = configuredSpawn == null || configuredSpawn.instanceId() <= 0
                    ? null : instances().impl(configuredSpawn.instanceId());
            var controlInstance = controlSpawn == null || controlSpawn.instanceId() <= 0
                    ? null : instances().impl(controlSpawn.instanceId());
            var configuredCat = configuredInstance == null ? null
                    : configuredInstance.baseEntity().filter(org.bukkit.entity.Cat.class::isInstance)
                    .map(org.bukkit.entity.Cat.class::cast).orElse(null);
            var controlCat = controlInstance == null ? null
                    : controlInstance.baseEntity().filter(org.bukkit.entity.Cat.class::isInstance)
                    .map(org.bukkit.entity.Cat.class::cast).orElse(null);
            var configuredOptions = configuredInstance == null ? null : mobConfig(configuredTargetId)
                    .getConfigurationSection("entity");
            var controlOptions = controlInstance == null ? null : mobConfig(controlTargetId)
                    .getConfigurationSection("entity");

            boolean imported = configuredCat != null && controlCat != null
                    && configuredOptions != null && controlOptions != null
                    && "SIAMESE".equalsIgnoreCase(configuredOptions.getString("cat-type"))
                    && configuredOptions.getBoolean("cat-sitting")
                    && "BLUE".equalsIgnoreCase(configuredOptions.getString("cat-collar-color"))
                    && "TABBY".equalsIgnoreCase(controlOptions.getString("cat-type"))
                    && !controlOptions.getBoolean("cat-sitting", true)
                    && "RED".equalsIgnoreCase(controlOptions.getString("cat-collar-color"));
            boolean applied = imported
                    && configuredCat.getCatType() == org.bukkit.entity.Cat.Type.SIAMESE
                    && configuredCat.isSitting()
                    && configuredCat.getCollarColor() == org.bukkit.DyeColor.BLUE
                    && controlCat.getCatType() == org.bukkit.entity.Cat.Type.TABBY
                    && !controlCat.isSitting()
                    && controlCat.getCollarColor() == org.bukkit.DyeColor.RED;
            getLogger().info("[自检] cat-options result=" + (imported && applied)
                    + " imported=" + imported
                    + " type=" + (configuredCat == null ? "missing" : configuredCat.getCatType().name())
                    + " sitting=" + (configuredCat != null && configuredCat.isSitting())
                    + " collar=" + (configuredCat == null ? "missing" : configuredCat.getCollarColor().name())
                    + " control-type=" + (controlCat == null ? "missing" : controlCat.getCatType().name())
                    + " control-sitting=" + (controlCat != null && controlCat.isSitting())
                    + " control-collar=" + (controlCat == null ? "missing" : controlCat.getCollarColor().name()));
        } catch (Throwable failure) {
            getLogger().warning("[自检] cat-options result=false error=" + failure);
        } finally {
            for (int instanceId : instanceIds) {
                try { instances().despawn(instanceId); } catch (RuntimeException ignored) { }
            }
            if (sourceRoot != null) {
                try (var paths = Files.walk(sourceRoot)) {
                    for (Path path : paths.sorted(java.util.Comparator.reverseOrder()).toList()) {
                        Files.deleteIfExists(path);
                    }
                } catch (IOException cleanupFailure) {
                    getLogger().warning("cat-options source cleanup failed=" + cleanupFailure);
                }
            }
            for (Path mobFile : mobFiles) {
                try { Files.deleteIfExists(mobFile); }
                catch (IOException cleanupFailure) {
                    getLogger().warning("cat-options target cleanup failed=" + cleanupFailure);
                }
            }
            if (!outputDirectoryExisted) {
                try { Files.deleteIfExists(outputDirectory); }
                catch (IOException ignored) { }
            }
        }
    }

