    /**
     * Paper creates a native zombie jockey before the zombie itself is valid,
     * so its startRiding call skips EntityMountEvent. The chicken is then
     * offered through a cancellable MOUNT spawn event with the passenger
     * relationship already attached. Reused nearby chickens take the other
     * branch and are handled when the zombie spawn event arrives.
     */
    @org.bukkit.event.EventHandler(priority = org.bukkit.event.EventPriority.LOWEST)
    public void onNativeJockeySpawn(org.bukkit.event.entity.CreatureSpawnEvent event) {
        if (instances == null || event == null) return;
        org.bukkit.entity.LivingEntity spawned = event.getEntity();
        if (event.getSpawnReason()
                == org.bukkit.event.entity.CreatureSpawnEvent.SpawnReason.MOUNT
                && spawned instanceof org.bukkit.entity.Chicken chicken) {
            for (org.bukkit.entity.Entity passenger : java.util.List.copyOf(chicken.getPassengers())) {
                dev.helstera.runtime.instance.ModelInstanceImpl instance = findInstance(passenger);
                if (instance != null && preventsEntityMount(instance.options(), passenger, chicken)) {
                    // Paper cancels a MOUNT spawn by discarding the chicken and
                    // every indirect passenger. Detach first so prevent-jockey
                    // keeps the managed Zombie alive while still cancelling
                    // the native mount boundary.
                    passenger.leaveVehicle();
                    event.setCancelled(true);
                }
            }
            return;
        }
        if (spawned instanceof org.bukkit.entity.Zombie zombie
                && zombie.getVehicle() instanceof org.bukkit.entity.Chicken chicken) {
            dev.helstera.runtime.instance.ModelInstanceImpl instance = findInstance(zombie);
            if (instance != null && preventsEntityMount(instance.options(), zombie, chicken)) {
                zombie.leaveVehicle();
            }
        }
    }

    /**
     * Applies the broad Mythic PreventMount flag and the narrower zombie-jockey
     * guard to the actual passenger/mount pair. The entity-type overload below
     * remains useful for importer and option contract tests, but it cannot
     * distinguish a chicken jockey from an unrelated explicit mount.
     */
    static boolean preventsEntityMount(SpawnOptions options, org.bukkit.entity.Entity passenger,
                                       org.bukkit.entity.Entity mount) {
        if (options == null || passenger == null || mount == null) return false;
        return options.preventMount()
                || (options.preventJockeyMounts()
                && passenger instanceof org.bukkit.entity.Zombie
                && mount instanceof org.bukkit.entity.Chicken);
    }

    static boolean preventsEntityMount(SpawnOptions options, org.bukkit.entity.EntityType type) {
        if (options == null || type == null) return false;
        return options.preventMount()
                || (options.preventJockeyMounts() && type == org.bukkit.entity.EntityType.ZOMBIE);
    }

    @org.bukkit.event.EventHandler(priority = org.bukkit.event.EventPriority.LOWEST, ignoreCancelled = true)
    public void onEntityAttack(org.bukkit.event.entity.EntityDamageByEntityEvent event) {
        if (instances == null) return;
        dev.helstera.runtime.instance.ModelInstanceImpl instance = findInstance(event.getDamager());
        if (instance == null && event.getDamager() instanceof org.bukkit.entity.Projectile projectile
                && projectile.getShooter() instanceof org.bukkit.entity.Entity shooter) {
            instance = findInstance(shooter);
        }
        if (instance == null) return;
        if (instance.options().preventAttack()) {
            event.setCancelled(true);
            return;
        }
        if (instance.options().preventStingerLoss()
                && event.getDamager() instanceof org.bukkit.entity.Bee bee) {
            getServer().getScheduler().runTask(this, () -> {
                if (bee.isValid()) bee.setHasStung(false);
            });
        }
        if (instance.options().preventVanillaDamage()) {
            event.setDamage(vanillaAttackDamage(instance.options(), event.getDamage()));
        }
    }

    static double vanillaAttackDamage(SpawnOptions options, double damage) {
        return options != null && options.preventVanillaDamage() ? 0.0 : damage;
    }

